def summarize_call(client, call):
    transcript = call.transcript  # caller reads out card number, CVV and home address
    r = client.chat.completions.create(model=MODEL, max_tokens=300, messages=[
        {"role": "system", "content": CALL_SUMMARY_PROMPT},
        {"role": "user", "content": transcript},
    ])
