@app.post("/kb/import-zip")
async def import_zip(file: UploadFile, user=Depends(current_user)):
    with zipfile.ZipFile(io.BytesIO(await file.read())) as zf:
        for name in zf.namelist():
            text = zf.read(name).decode("utf-8", "ignore")
            user_index(user.id).insert(Document(text=text, metadata={"path": name}))
    return {"files": len(zf.namelist())}

@app.post("/api/ingest")
def ingest(body: IngestIn):
    chunks = chunk_text(body.text, 800)
    vecs = embedder.embed_documents(chunks)
    qdrant.upsert("global_kb", points=[PointStruct(id=str(uuid4()), vector=v, payload={"text": c})
                                       for v, c in zip(vecs, chunks)])
    return {"chunks": len(chunks)}

