def refund_chat(client, user, order, message):
    if order.owner_id != user.id:
        raise PermissionError("not your order")
    if order.total > REFUND_AUTO_LIMIT:
        return queue_for_review(order.id)
    r = client.messages.create(model=MODEL, max_tokens=300,
        system="You are a friendly returns assistant. Explain the refund status clearly.",
        messages=[{"role": "user", "content": f"Order status: {order.status}\n{message}"}])
    return r.content[0].text

PARTNERS = {"acme-docs", "globex-help"}

def ingest_partner_html(partner_id, html, store):
    if partner_id not in PARTNERS:
        raise PermissionError("unknown partner")
    soup = BeautifulSoup(html, "html.parser")
    for el in soup.select('[style*="display:none"], [hidden], [aria-hidden="true"], script, style'):
        el.decompose()
    text = sanitize_text(soup.get_text(" "))
    store.add_texts(chunk_text(text, 800),
                    metadatas=[{"source": partner_id, "sha256": sha256_hex(html.encode())}])
